scripts:
(() => {
  const form = document.querySelector('#fit-form');
  const title = document.querySelector('#result-title');
  const copy = document.querySelector('#result-copy');
  form.addEventListener('submit', (event) => {
    event.preventDefault();
    const questions = Number(document.querySelector('#questions').value) || 0;
    const domains = Number(document.querySelector('#domains').value) || 1;
    const capabilities = document.querySelector('#capabilities').value === 'yes';
    const resultParams = { questions_per_month: questions, domains, needs_actions: capabilities };
    if (questions > 20000 || domains > 10) {
      title.textContent = 'Custom or enterprise boundary';
      copy.textContent = 'Your inputs are above the published Pro boundary. Compare enterprise options or ask the provider to confirm a custom capacity and workflow.';
      window.trackAffiliateEvent?.('affiliate_fit_calculator_complete', { ...resultParams, fit_boundary: 'custom_or_enterprise' });
      return;
    }
    if (questions > 5000 || domains > 5 || capabilities) {
      title.textContent = 'Growth or Pro boundary';
      copy.textContent = 'The published Growth boundary is a better starting point when you need multiple domains, operational actions, analytics, or more than 5,000 monthly credits. Move to Pro if your volume or domain count is higher.';
      window.trackAffiliateEvent?.('affiliate_fit_calculator_complete', { ...resultParams, fit_boundary: 'growth_or_pro' });
      return;
    }
    if (questions > 1000 || domains > 1) {
      title.textContent = 'Growth boundary';
      copy.textContent = 'The published Growth boundary is the closer fit for more than one domain or more than 1,000 monthly credits. Use the trial to test your real questions before paying.';
      window.trackAffiliateEvent?.('affiliate_fit_calculator_complete', { ...resultParams, fit_boundary: 'growth' });
      return;
    }
    title.textContent = 'Starter boundary';
    copy.textContent = 'The published Starter boundary is the closest fit for one domain and up to 1,000 monthly credits. Treat it as a pilot and test known and unknown questions before committing.';
    window.trackAffiliateEvent?.('affiliate_fit_calculator_complete', { ...resultParams, fit_boundary: 'starter' });
  });
})();
